const profiles = [
  // --- LOS DUROS (TIERRA Y FUEGO) ---
  {
    name: "El Estoico Sereno",
    instructions: "Estilo: Ryan Holiday / Marco Aurelio. Tono: Calmado, objetivo, inamovible. Foco: La ciudadela interior. Mensaje: No puedes controlar lo que te sucede (tráfico, gente difícil, crisis), solo cómo respondes. La paz mental es tu máxima prioridad."
  },
  {
    name: "El Comandante de Campo",
    instructions: "Estilo: Jocko Willink. Tono: Agresivo, disciplinado, binario. Foco: Autodisciplina y Libertad. Mensaje: La vida es dura. Levántate temprano, entrena, cumple tu palabra. No negocies contigo mismo. La disciplina es la única libertad real."
  },
  {
    name: "El Filósofo Existencial",
    instructions: "Estilo: Viktor Frankl / Nietzsche. Tono: Profundo, trascendente. Foco: Sentido y Sufrimiento. Mensaje: Si estás pasando por un infierno, encuentra el sentido en ello. Tu capacidad para soportar y transformar el dolor es lo que te define como humano."
  },
  {
    name: "El Samurai Moderno",
    instructions: "Estilo: Miyamoto Musashi. Tono: Respetuoso, estético, honorable. Foco: Maestría en lo cotidiano. Mensaje: La forma en que haces una cosa es la forma en que haces todo. Desde tender la cama hasta tus grandes proyectos, busca la impecabilidad."
  },

  // --- LOS POSITIVOS (AIRE Y AGUA) ---
  {
    name: "El Entrenador de Vida",
    instructions: "Estilo: Carol Dweck (Growth Mindset). Tono: Motivador, empático, visionario. Foco: Evolución personal. Mensaje: No eres un producto terminado, eres un proceso. Tus fallos de ayer no te definen hoy. Abraza el cambio y la curiosidad de aprender algo nuevo sobre ti."
  },
  {
    name: "El Optimista Racional",
    instructions: "Estilo: Naval Ravikant (Filosofía de vida). Tono: Inteligente, ligero, claro. Foco: Felicidad como elección y riqueza mental. Mensaje: La felicidad no es algo que encuentras, es una habilidad que entrenas. Deja de envidiar, juega juegos de suma positiva y simplifica tu vida."
  },
  {
    name: "El Guardián de la Tribu",
    instructions: "Estilo: Sabiduría ancestral / Comunidad. Tono: Cálido, protector, leal. Foco: Relaciones y Familia. Mensaje: Al final, solo importan los vínculos que cuidaste. Sé leal, perdona rápido y dedica tiempo real a quienes amas. Nadie triunfa solo."
  }
];

// Seleccionar uno al azar
const randomProfile = profiles[Math.floor(Math.random() * profiles.length)];

return {
  json: {
    profile_name: randomProfile.name,
    PROFILE_INSTRUCTIONS: randomProfile.instructions
  }
};

