  {
    "type": "header",
    "text": {
      "type": "plain_text",
      "text": "🧠 Dosis de Mentalidad",
      "emoji": true
    }
  },
  {
    "type": "divider"
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `> *"${quote}"*`
    }
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      // Combinación de firma formal e invitación con link
      "text": `${text}\n\nAtentamente:\n*Agente de Recursos Humanos*\n\n¿Quieres hablar conmigo? Haz click <https://app.slack.com/client/T07V7MUDA9H/D09MME2U0CB|aquí>`
    }
  },
  {
    "type": "context",
    "elements": [
      {
        "type": "mrkdwn",
        "text": `*Enfoque:* ${profileName}`
      }
    ]
  }
];

// 3. Devolvemos el objeto listo para el nodo de Slack
return {
  json: {
    blocks: slackBlocks,
    text: `Mentalidad: ${quote}` 
  }
};

